<script setup lang="ts">
import { ref, watch } from 'vue';

const props = defineProps<{
  modelValue: 'grid' | 'list';
}>();

const emit = defineEmits<{
  (e: 'update:modelValue', value: 'grid' | 'list'): void;
}>();

const isListMode = ref(props.modelValue === 'list');

watch(() => props.modelValue, (newVal) => {
  isListMode.value = newVal === 'list';
});

const toggleMode = () => {
  isListMode.value = !isListMode.value;
  const mode = isListMode.value ? 'list' : 'grid';
  emit('update:modelValue', mode);
  // 保存到本地存储
  localStorage.setItem('articleViewMode', mode);
  // 触发自定义事件通知 ArticleList
  window.dispatchEvent(new CustomEvent('viewModeChange', { detail: mode }));
};
</script>

<template>
  <label class="view-mode-switch">
    <input 
      type="checkbox" 
      :checked="isListMode"
      @change="toggleMode"
    />
    <span class="switch-slider">
      <!-- 网格图标 -->
